// Product-level building blocks on top of shadcn/ui. Pages import from here; the primitives
// they are built on live in ./ui/*.jsx (generated by the shadcn CLI).
import React from 'react';
import { AlertCircle, CheckCircle2 } from 'lucide-react';
import { cn } from '@/lib/utils';
import { Card, CardAction, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Skeleton as ShadSkeleton } from '@/components/ui/skeleton';
import { Alert, AlertDescription } from '@/components/ui/alert';

/** A titled card. `aside` sits top-right (actions, meta). `pad={false}` lets tables run edge to edge. */
export function Panel({ title, description, aside, children, className, pad = true, contentClassName }) {
  return (
    <Card className={cn('gap-0 py-0 shadow-none', className)}>
      {(title || aside) && (
        <CardHeader className="flex flex-row flex-wrap items-center justify-between gap-x-4 gap-y-1 px-5 pt-4 pb-3">
          <div className="min-w-0">
            {title && <CardTitle className="text-sm font-semibold tracking-tight">{title}</CardTitle>}
            {description && <CardDescription className="mt-0.5 text-xs">{description}</CardDescription>}
          </div>
          {aside && <CardAction className="col-start-auto row-start-auto flex items-center gap-2 self-center text-xs text-muted-foreground">{aside}</CardAction>}
        </CardHeader>
      )}
      <CardContent className={cn(pad ? 'px-5 pb-5' : 'px-0 pb-0', !title && !aside && pad && 'pt-5', contentClassName)}>{children}</CardContent>
    </Card>
  );
}

const TONES = {
  good: 'bg-success-soft text-success',
  warn: 'bg-warning-soft text-warning',
  bad: 'bg-danger-soft text-danger',
  gold: 'bg-brand-soft text-brand-foreground',
  ink: 'bg-primary text-primary-foreground',
  neutral: 'bg-muted text-muted-foreground',
  mute: 'bg-muted text-muted-foreground',
};
const DOT = { good: 'bg-success', warn: 'bg-warning', bad: 'bg-danger', gold: 'bg-brand', ink: 'bg-foreground', neutral: 'bg-muted-foreground/60', mute: 'bg-muted-foreground/60' };

/** Small status chip. `dot` adds a leading status dot (used for decisions and states). */
export function Pill({ tone = 'mute', children, title, dot = false, className }) {
  return (
    <span title={title} className={cn('inline-flex h-5 items-center gap-1.5 rounded-md px-1.5 text-[11px] font-medium whitespace-nowrap', TONES[tone] || TONES.mute, className)}>
      {dot && <span className={cn('size-1.5 rounded-full', DOT[tone] || DOT.mute)} aria-hidden="true" />}
      {typeof children === 'string' ? children.charAt(0).toUpperCase() + children.slice(1) : children}
    </span>
  );
}

const DECISION_TONE = { Scale: 'good', Continue: 'neutral', Change: 'warn', Stop: 'bad' };
export const Decision = ({ value, title }) => <Pill tone={DECISION_TONE[value] || 'mute'} title={title} dot>{value}</Pill>;

/** Marks where a number comes from (source data vs assumption vs threshold). */
export function Kind({ kind }) {
  const map = { assumption: ['gold', 'Assumption'], threshold: ['mute', 'Threshold'], source: ['good', 'Source data'], simulated: ['gold', 'Simulated'] };
  const [tone, label] = map[kind] || map.source;
  return <Pill tone={tone} className="ml-1.5 align-middle">{label}</Pill>;
}

/** Progress toward a goal. tone: 'ink' (default) or 'gold' (goal stage). `goal` draws a target tick. */
export function Meter({ value, goal, tone = 'ink', label, className }) {
  const v = Math.max(0, Math.min(1, value ?? 0));
  return (
    <div className={cn('relative h-1.5 rounded-full bg-muted', className)} role="meter" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(v * 100)} aria-label={label}>
      <span className={cn('absolute inset-y-0 left-0 rounded-full', tone === 'gold' ? 'bg-brand' : 'bg-foreground')} style={{ width: `${v * 100}%` }} />
      {goal != null && <span className="absolute -top-1 h-3.5 w-0.5 rounded-full bg-brand" style={{ left: `${Math.min(1, goal) * 100}%` }} />}
    </div>
  );
}

/** Dialog with a title. Esc, outside click and the close button all call onClose. */
export function Modal({ title, description, onClose, children, wide }) {
  return (
    <Dialog open onOpenChange={(o) => !o && onClose()}>
      <DialogContent className={cn('max-h-[90vh] overflow-y-auto', wide ? 'sm:max-w-3xl' : 'sm:max-w-lg')}>
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          {description ? <DialogDescription>{description}</DialogDescription> : <DialogDescription className="sr-only">{title}</DialogDescription>}
        </DialogHeader>
        {children}
      </DialogContent>
    </Dialog>
  );
}

/** Label + control + optional hint. Wrap one input/select/textarea. */
export function Field({ label, children, hint, className }) {
  return (
    <Label className={cn('flex flex-col items-stretch gap-1.5 font-normal', className)}>
      <span className="text-xs font-medium text-muted-foreground">{label}</span>
      {children}
      {hint && <span className="text-xs text-muted-foreground">{hint}</span>}
    </Label>
  );
}

export const Empty = ({ children, className }) => (
  <div className={cn('rounded-lg border border-dashed px-4 py-8 text-center text-sm text-muted-foreground', className)}>{children}</div>
);

export function Notice({ tone = 'bad', children }) {
  if (!children) return null;
  const good = tone === 'good';
  return (
    <Alert variant={good ? 'default' : 'destructive'} role={good ? 'status' : 'alert'} className={good ? 'border-success/30 bg-success-soft text-success' : ''}>
      {good ? <CheckCircle2 /> : <AlertCircle />}
      <AlertDescription className={good ? 'text-success' : ''}>{children}</AlertDescription>
    </Alert>
  );
}

export const Skeleton = ({ h = 120, className }) => <ShadSkeleton className={cn('w-full rounded-xl', className)} style={{ height: h }} />;

/** Native select styled like shadcn inputs (kept native for forms with many options and for mobile). */
export const NativeSelect = React.forwardRef(function NativeSelect({ className, ...props }, ref) {
  return (
    <select ref={ref} className={cn('h-9 w-full min-w-0 rounded-md border border-input bg-transparent px-2.5 text-sm shadow-xs outline-none transition-[color,box-shadow] focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:opacity-50 dark:bg-input/30', className)} {...props} />
  );
});

/** A big figure with label, used in KPI strips. */
export function Stat({ label, value, sub, className, children }) {
  return (
    <div className={cn('flex flex-col gap-1', className)}>
      <span className="text-xs font-medium text-muted-foreground">{label}</span>
      <span className="text-2xl font-semibold tracking-tight">{value}</span>
      {children}
      {sub && <span className="text-xs text-muted-foreground">{sub}</span>}
    </div>
  );
}
